/**********************
 *  STATIC VARIABLES
 **********************/
static bool have_input = false;
static bool s_is_star = false;

/****************************************/
/*       AIC Manual ADD Code            */
/****************************************/
static int32_t HandleDialerResult(int32_t result)
{
    LV_LOG_INFO("[%s],dialer result = %d", __func__, result);
    if(0 != result) {
        comp_msgbox_info_t msgbox_info = {0};
        msgbox_info.timeout = 3000;
        msgbox_info.title = LV_SYMBOL_WARNING;
        msgbox_info.content = "Call failed!!!";
        comp_msgbox_create(lv_scr_act(), &msgbox_info);
    } else {
        alv_am_win_enter(NULL, "call_outgoing", NULL);
    }

    return 0;
}

void dialer_win_active(lv_obj_t *win, void *p_param)
{
    ui_dialer_init();
    if(NULL != p_param) {
        call_enter_param_t *p_enter_param = (call_enter_param_t *)p_param;
        char *phone_num = p_enter_param->phone_num;
        LV_LOG_INFO("the phone num is %s", phone_num);
        lv_textarea_add_text(ui_TextareaDialer, phone_num);
        have_input = true;
    }

    lv_group_add_obj(lv_group_get_default(), ui_Dialer);
}
void dialer_win_deactive(lv_obj_t *win, void *p_param)
{
    lv_obj_del(ui_Dialer);
    ui_Dialer = NULL;
}
void dialer_win_focus(lv_obj_t *win, void *p_param)
{
    lv_disp_load_scr(ui_Dialer);
    lv_group_focus_obj(ui_TextareaDialer);

    SHOW_STATUSBAR;
    /* display softkey */
    softkey_t softkey_right ={0};
    if(strlen(lv_textarea_get_text(ui_TextareaDialer)) == 0) {
        softkey_right.p_txt = "Back";
    } else {
        softkey_right.p_txt = "Delete";
    }
    SHOW_SOFTKEY(NULL, NULL, &softkey_right);
}
/****************************************/
/*       AIC Manual ADD Code            */
/****************************************/
void DialNumber(void)
{
    const char *p_temp_phone_num = NULL;
    char phone_num[33] = {0};

    p_temp_phone_num = lv_textarea_get_text(ui_TextareaDialer);

    memcpy(phone_num, p_temp_phone_num, 32);
    LV_LOG_USER("[key test] phone_num = %s",phone_num);
    call_flow_dial(phone_num, HandleDialerResult);
}

void DialerTextareaDialerKey(lv_event_t * e)
{
    // Your code here
    lv_event_code_t code = lv_event_get_code(e);
    uint32_t key = lv_event_get_key(e);
    if(s_is_star){
        if(code == LV_EVENT_LONG_PRESSED){
            LV_LOG_USER("[key test] LV_EVENT_LONG_PRESSED,star ");
            lv_textarea_del_char(ui_TextareaDialer);
            lv_textarea_add_char(ui_TextareaDialer, '+');
            lv_indev_wait_release(lv_indev_get_act());
            s_is_star = false;
        }
    }
    if(code == LV_EVENT_KEY){
        s_is_star = false;
        switch (key) {
        case LV_KEY_END:
            alv_am_app_exit(NULL, "call", NULL);
            LV_LOG_USER("[key test] back to idle app");
            have_input = false;
            return;
            break;
        case LV_KEY_GREEN:
            DialNumber();
            LV_LOG_USER("[key test] LV_KEY_GREEN ,go to outgoing win");
            break;
        case LV_KEY_BACKSPACE:
            if (strlen(lv_textarea_get_text(ui_TextareaDialer)) == 0) {
                LV_LOG_USER("[key test] LV_KEY_BACKSPACE ,text length = 0");
                if (have_input == false) {
                    lv_indev_wait_release(lv_indev_get_act());
                    alv_am_app_exit(NULL, "call", NULL);
                    LV_LOG_USER("[key test] LV_KEY_BACKSPACE , back to idle app");
                    LV_LOG_USER("[key test] LV_KEY_BACKSPACE , have_input = false");
                    return;
                }else{
                    LV_LOG_USER("[key test] LV_KEY_BACKSPACE , have_input = true");
                    have_input = false;
                }
            }
            break;
        case LV_KEY_0:
        case LV_KEY_1:
        case LV_KEY_2:
        case LV_KEY_3:
        case LV_KEY_4:
        case LV_KEY_5:
        case LV_KEY_6:
        case LV_KEY_7:
        case LV_KEY_8:
        case LV_KEY_9:
            have_input = true;
            LV_LOG_INFO("use default key event");
            break;
        case LV_KEY_HASH:
            lv_textarea_add_char(ui_TextareaDialer, '#');
            LV_LOG_USER("[key test] LV_KEY_HASH ");
            have_input = true;
            break;
        case LV_KEY_STAR:
            LV_LOG_USER("[key test] LV_KEY_STAR ");
            lv_textarea_add_char(ui_TextareaDialer, '*');
            have_input = true;
            s_is_star = true;
            break;
        default:
            LV_LOG_USER("[key test] dialer,other keys");
            if (strlen(lv_textarea_get_text(ui_TextareaDialer)) != 0){
                have_input = true;
            }
            LV_LOG_USER("[key test] key = %d , have_input = %d",key,have_input);
            break;
        }
        if (true == have_input){
            softkey_t softkey_right ={0};
            softkey_right.p_txt = "Delete";
            SHOW_SOFTKEY(NULL, NULL, &softkey_right);
        }else{
            LV_LOG_USER("[key test] false == have_input , back");
            softkey_t softkey_right ={0};
            softkey_right.p_txt = "Back";
            SHOW_SOFTKEY(NULL, NULL, &softkey_right);
        }
    }
}
